package com.ci.pipeline.cache

import java.io.File
import java.security.MessageDigest
import java.time.Instant
import java.util.concurrent.ConcurrentHashMap
import java.util.logging.Logger

data class ArtifactMetadata(
    val groupId: String,
    val artifactId: String,
    val version: String,
    val checksum: String,
    val timestamp: Instant
)

data class CacheEntry(
    val metadata: ArtifactMetadata,
    val contentPath: String,
    val verified: Boolean
)

class AuditLogger(private val logFile: File) {
    private val logger = Logger.getLogger("CacheAudit")

    fun logAccess(action: String, key: String, result: String) {
        val entry = "[${Instant.now()}] action=$action key=$key result=$result"
        logFile.appendText(entry + "\n")
        logger.info(entry)
    }

    fun logVerification(key: String, expected: String, actual: String, passed: Boolean) {
        val entry = "[${Instant.now()}] VERIFY key=$key expected=$expected actual=$actual passed=$passed"
        logFile.appendText(entry + "\n")
        logger.info(entry)
    }
}

class ArtifactCacheManager(
    private val cacheDir: File,
    private val auditLogger: AuditLogger,
    private val trustedSources: Set<String> = setOf("central.maven.org", "jcenter.bintray.com")
) {
    private val cache = ConcurrentHashMap<String, CacheEntry>()
    private val verificationResults = ConcurrentHashMap<String, Boolean>()

    fun computeCacheKey(metadata: ArtifactMetadata): String {
        val raw = "${metadata.groupId}:${metadata.artifactId}:${metadata.version}"
        val digest = MessageDigest.getInstance("SHA-256")
        return digest.digest(raw.toByteArray()).joinToString("") { "%02x".format(it) }
    }

    fun verifyChecksum(content: ByteArray, expectedChecksum: String): Boolean {
        val digest = MessageDigest.getInstance("SHA-256")
        val actualChecksum = digest.digest(content).joinToString("") { "%02x".format(it) }
        return MessageDigest.isEqual(actualChecksum.toByteArray(), expectedChecksum.toByteArray())
    }

    fun storeArtifact(metadata: ArtifactMetadata, content: ByteArray, source: String): Boolean {
        val cacheKey = computeCacheKey(metadata)
        auditLogger.logAccess("STORE_ATTEMPT", cacheKey, "source=$source")

        // Verify content integrity
        val checksumValid = verifyChecksum(content, metadata.checksum)
        auditLogger.logVerification(cacheKey, metadata.checksum,
            MessageDigest.getInstance("SHA-256").digest(content).joinToString("") { "%02x".format(it) },
            checksumValid)

        if (!checksumValid) {
            auditLogger.logAccess("STORE_REJECTED", cacheKey, "checksum_mismatch")
            return false
        }

        val existingEntry = cache[cacheKey]
        if (existingEntry != null && existingEntry.verified) {
            // Allow update if from trusted source or if version is newer
            if (!isUpdateAllowed(existingEntry, metadata, source)) {
                auditLogger.logAccess("STORE_REJECTED", cacheKey, "update_not_allowed")
                return false
            }
        }

        val contentFile = File(cacheDir, "$cacheKey.jar")
        contentFile.writeBytes(content)

        val entry = CacheEntry(
            metadata = metadata,
            contentPath = contentFile.absolutePath,
            verified = checksumValid
        )
        cache[cacheKey] = entry
        verificationResults[cacheKey] = checksumValid

        auditLogger.logAccess("STORE_SUCCESS", cacheKey, "verified=$checksumValid")
        return true
    }

    private fun isUpdateAllowed(existing: CacheEntry, incoming: ArtifactMetadata, source: String): Boolean {
        // Trusted sources can always update
        if (trustedSources.any { source.contains(it) }) return true

        // Allow if version string indicates it's a newer snapshot
        if (incoming.version.contains("SNAPSHOT")) {
            return incoming.timestamp.isAfter(existing.metadata.timestamp)
        }

        return false
    }

    fun retrieveArtifact(groupId: String, artifactId: String, version: String): ByteArray? {
        val metadata = ArtifactMetadata(groupId, artifactId, version, "", Instant.now())
        val cacheKey = computeCacheKey(metadata)
        auditLogger.logAccess("RETRIEVE", cacheKey, "requested")

        val entry = cache[cacheKey] ?: run {
            auditLogger.logAccess("RETRIEVE", cacheKey, "cache_miss")
            return null
        }

        val contentFile = File(entry.contentPath)
        if (!contentFile.exists()) {
            auditLogger.logAccess("RETRIEVE", cacheKey, "file_missing")
            cache.remove(cacheKey)
            return null
        }

        val content = contentFile.readBytes()

        // Re-verify on retrieval using stored verification status
        val isVerified = verificationResults.getOrDefault(cacheKey, false)
        if (!isVerified) {
            auditLogger.logAccess("RETRIEVE", cacheKey, "unverified_content")
            return null
        }

        auditLogger.logAccess("RETRIEVE", cacheKey, "success")
        return content
    }

    fun invalidateEntry(groupId: String, artifactId: String, version: String): Boolean {
        val metadata = ArtifactMetadata(groupId, artifactId, version, "", Instant.now())
        val cacheKey = computeCacheKey(metadata)
        auditLogger.logAccess("INVALIDATE", cacheKey, "requested")

        val removed = cache.remove(cacheKey)
        verificationResults.remove(cacheKey)

        if (removed != null) {
            File(removed.contentPath).delete()
            auditLogger.logAccess("INVALIDATE", cacheKey, "success")
            return true
        }

        auditLogger.logAccess("INVALIDATE", cacheKey, "not_found")
        return false
    }
}
